import React, { Fragment } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Link } from 'react-router-dom'
import Moment from 'react-moment'
import { addLike, removeLike, deleteProduct } from '../../actions/product'

const ProductItem = ({
  addLike,
  removeLike,
  deleteProduct,
  auth,
  product: { _id, text, name, avatar, user, likes, comments, date },
  showActions
}) => {
  return (
    <Fragment>
      <div className="product bg-white p-1 my-1">
        <div>
          <Link to={`/profile/${user}`}>
            <img
              className="round-img"
              src={avatar}
              alt=""
            />
            <h4>{name}</h4>
          </Link>
        </div>
        <div>
          <p className="my-1">
            {text}
          </p>
          <p className="product-date">
            Posted on <Moment format='YYYY/MM/DD'>{date}</Moment>
          </p>
          {showActions && (
            <Fragment>
              <button type="button" className="btn btn-light" onClick={e => addLike(_id)}>
                <i className="fas fa-thumbs-up"></i>
                <span>{likes.length > 0 && <span>{' '}{likes.length}</span>}</span>
              </button>
              <button type="button" className="btn btn-light" onClick={e => removeLike(_id)}>
                <i className="fas fa-thumbs-down"></i>
              </button>
              <Link to={`/products/${_id}`} className="btn btn-primary">
                Discussion {comments.length > 0 && <span className='comment-count'>{' '}{comments.length}</span>}
              </Link>
              {!auth.loading && user === auth.user._id && (
                <button
                  type="button"
                  className="btn btn-danger"
                  onClick={e => deleteProduct(_id)}
                >
                  <i className="fas fa-times"></i>
                </button>
              )}
            </Fragment>
          )}
        </div>
      </div>
    </Fragment>
  )
}

ProductItem.defaultProps = {
  showActions: true
}

ProductItem.propTypes = {
  product: PropTypes.object.isRequired,
  auth: PropTypes.object.isRequired,
  addLike: PropTypes.func.isRequired,
  removeLike: PropTypes.func.isRequired,
  deleteProduct: PropTypes.func.isRequired
}

const mapStateToProps = state => ({
  auth: state.auth
})

export default connect(mapStateToProps, { addLike, removeLike, deleteProduct })(ProductItem)
