import React, { useEffect , Fragment} from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { getCurrentProfile, clearProfile, deleteAccount } from '../../actions/profile'
import Spinner from '../layout/Spinner'
import { Link } from 'react-router-dom'
import DashboardActions from './DashboardActions'
import Experience from './Experience'
import Education from './Education'
const Dashboard = ({ getCurrentProfile, clearProfile, auth, profile:{loading, profile} }) => {

  useEffect(() => {
    getCurrentProfile();
  }, [getCurrentProfile]);

  return loading && profile === null ? <Spinner />:<Fragment> 
    <h1 className='large text-primary'>Dashboard</h1>
    <p className='lead'>
    <i className='fas fa-user'></i>{' '}
    Welcome {auth.user && auth.user.name}
    </p>
  { profile !== null ? <>
    <DashboardActions />
    <Experience experience={profile.experience} />
    <Education education={profile.education} />

    <button className='btn btn-danger' onClick={() => deleteAccount()}>
      <i className='fas fa-user-minus'></i>{' '}Delete My Account
    </button>
  </> : <>
  <p>You have not yet setup a profile</p>
  <Link to ='/create-profile' className='btn btn-primary my-1'>Create Profile</Link>
  </>}
  </Fragment>
}

Dashboard.propTypes = {
  getCurrentProfile: PropTypes.func.isRequired,
  clearProfile: PropTypes.func.isRequired,
  deleteAccount: PropTypes.func.isRequired,
  auth: PropTypes.object.isRequired,
  profile: PropTypes.object.isRequired
}

const mapStateToProps = state => ({
  auth: state.auth,
  profile: state.profile
})

export default connect(mapStateToProps, { getCurrentProfile, clearProfile, deleteAccount })(Dashboard)
